  "steps": [
    {
      "id": "s1",
      "description": "List and read all project documents to understand the radiator candidates, their properties (refractive index, transparency, ageing characteristics), and the simulation specifications."
    },
    {
      "id": "s2",
      "description": "Filter radiator candidates based on the hard constraint of transparency loss after 10-year-equivalent humidity ageing test (must not exceed 10%). Identify which candidates meet this requirement."
    },
    {
      "id": "s3",
      "description": "For each viable radiator candidate that passed the ageing constraint, run simulations at multiple thickness values within the 1-6 cm range (e.g., 2, 3, 4, 5 cm) to map the pion/kaon separation performance as a function of thickness."
    },
    {
      "id": "s4",
      "description": "Analyze simulation results to verify which radiator-thickness combinations meet the hard constraint of at least 3.5 sigma pion/kaon separation at 10 GeV/c."
    },
    {
      "id": "s5",
      "description": "Among all combinations that satisfy both hard constraints, identify the optimal radiator and thickness that provides the best pion/kaon separation at 10 GeV/c. Record the final recommended radiator type and thickness value."
    }
  ]
}
